using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Draftmaster.MasterDraft;
using Draftmaster.Tracks;
using NUnit.Framework;

// Master Draft's challenges: Assets/Resources/MasterDraft/Challenges.json (generated by Tools/masterdraft_export.py
// from Draftmaster 2's EventData.cs) and Core Challenges.cs — which events run in a week, chapter unlocks and entry,
// chapter progress and prize resolution. Engine-free — reads the files off disk — so it also runs under
// `dotnet test Tools/HeadlessTests`.
public class MasterDraftChallengeTests
{
    // DM2's events in order and how many chapters each has ("All Stars" is commented out, "The Final 4" was a
    // PlayerPrefs special with no chapters).
    static readonly (string id, string type, int chapters)[] ExpectedEvents =
    {
        ("ol_seven_time", "Progression", 8), ("the_intimidator", "Progression", 8), ("the_closer", "Progression", 11),
        ("modern_era", "Replay", 3), ("classics", "Replay", 2),
    };

    static string projectRoot;

    static string ProjectRoot()
    {
        if (projectRoot != null) return projectRoot;
        foreach (var start in new[] { TestContext.CurrentContext.TestDirectory, Directory.GetCurrentDirectory() })
        {
            for (var dir = new DirectoryInfo(start); dir != null; dir = dir.Parent)
                if (File.Exists(Path.Combine(dir.FullName, "Assets", "Resources", "MasterDraft", "Challenges.json")))
                    return projectRoot = dir.FullName;
        }
        Assert.Fail("Assets/Resources/MasterDraft/Challenges.json not found above " + TestContext.CurrentContext.TestDirectory);
        return null;
    }

    static string Resource(string path) => File.ReadAllText(Path.Combine(ProjectRoot(), "Assets", "Resources", path + ".json"));

    static ChallengeCatalog LoadChallenges()
    {
        var c = ChallengeCatalog.FromJson(Resource(ChallengeCatalog.ResourcePath));
        Assert.IsNotNull(c, "Challenges.json did not parse");
        return c;
    }

    static CarCatalog LoadCars()
    {
        var c = CarCatalog.FromJson(Resource(CarCatalog.ResourcePath));
        Assert.IsNotNull(c, "Cars.json did not parse");
        return c;
    }

    static CarDef Car(string id, int number, string team = "HEN", string manu = "CHV", int rarity = 1,
        string type = "Closer", string driver = "Driver") =>
        new CarDef { id = id, carset = id.Split('_')[0], number = number, team = team, manufacturer = manu, rarity = rarity, type = type, driver = driver };

    static CarCatalog SmallCatalog() => new CarCatalog(new CarCatalogFile
    {
        version = 1,
        cars = new List<CarDef>
        {
            Car("t_1", 1, rarity: 1), Car("t_2", 2, rarity: 1), Car("t_3", 3, rarity: 1), Car("t_4", 4, rarity: 1),
            Car("t_5", 5, rarity: 2), Car("t_48", 48, rarity: 3, driver: "Johnson"),
        },
    });

    static ChallengeEvent Event(string type, params string[] chapterIds)
    {
        var e = new ChallengeEvent { id = "ev", name = "Ev", type = type, weeks = new List<int> { 1, 5 } };
        foreach (var id in chapterIds)
            e.chapters.Add(new ChallengeChapter
            {
                id = id, eventId = "ev", track = "Daytona", baseLaps = 4,
                prize = new ChallengePrize { kind = ChallengePrizeKind.Car, code = "Johnson", cars = new List<string> { "t_48" }, gears = 20 },
            });
        return e;
    }

    // ---- Challenges.json --------------------------------------------------------------------------------

    [Test]
    public void FileHasEveryEventAndChapterInOrder()
    {
        var file = (ChallengesFile)ProfileJson.Read(Resource(ChallengeCatalog.ResourcePath), typeof(ChallengesFile));
        Assert.AreEqual(1, file.version);
        Assert.AreEqual(13, file.cycleWeeks);
        var c = new ChallengeCatalog(file);
        CollectionAssert.AreEqual(ExpectedEvents.Select(e => e.id).ToArray(), c.Events.Select(e => e.id).ToArray());
        foreach (var (id, type, chapters) in ExpectedEvents)
        {
            Assert.AreEqual(type, c.Get(id).type, id);
            Assert.AreEqual(chapters, c.Get(id).chapters.Count, id);
        }
        var ids = c.Events.SelectMany(e => e.chapters).Select(ch => ch.id).ToList();
        Assert.AreEqual(ids.Count, ids.Distinct().Count());
        foreach (var e in c.Events)
            foreach (var ch in e.chapters)
            {
                Assert.AreEqual(e.id, ch.eventId, ch.id);
                Assert.AreSame(ch, c.GetChapter(ch.id));
                Assert.AreSame(e, c.EventOf(ch));
            }
    }

    [Test]
    public void CommentedOutAndPlayerPrefsChaptersAreNotExported()
    {
        var names = LoadChallenges().Events.SelectMany(e => e.chapters).Select(ch => ch.name).ToList();
        CollectionAssert.DoesNotContain(names, "Gladiators");        // All Stars, in /* */
        CollectionAssert.DoesNotContain(names, "Austin As Moses");   // Modern Era, in /* */
        Assert.IsNull(LoadChallenges().Get("the_final_4"));
    }

    [Test]
    public void WeeksMatchDm2()
    {
        var c = LoadChallenges();
        CollectionAssert.AreEqual(new[] { 4, 8, 12 }, c.Get("ol_seven_time").weeks);
        CollectionAssert.AreEqual(new[] { 2, 6, 10 }, c.Get("the_intimidator").weeks);
        CollectionAssert.AreEqual(new[] { 1, 5, 9 }, c.Get("the_closer").weeks);
        CollectionAssert.AreEqual(Enumerable.Range(1, 12).ToArray(), c.Get("modern_era").weeks);
    }

    [Test]
    public void FirstJohnsonChapterMatchesDm2()
    {
        var ch = LoadChallenges().GetChapter("ol_seven_time_where_it_all_began");
        Assert.IsNotNull(ch);
        CollectionAssert.AreEqual(new[] { 0, 0 }, ch.dm2Index);
        Assert.AreEqual(8, ch.aiLevel);
        Assert.AreEqual(5, ch.restriction.minLevel);
        Assert.AreEqual(2, ch.restriction.minClass);
        Assert.AreEqual(RestrictionRule.Team, ch.restriction.rule);
        Assert.AreEqual("HEN", ch.restriction.value);
        Assert.AreEqual("Michigan", ch.track, "DM2 track 5 (Fontana) maps like Series.json");
        Assert.AreEqual(5, ch.dm2Track);
        Assert.AreEqual(0, ch.raceLaps);
        Assert.IsFalse(ch.ProvidesCar);
        Assert.AreEqual(ChallengePrizeKind.Car, ch.prize.kind);
        CollectionAssert.AreEqual(new[] { "cup20_48" }, ch.prize.cars);
        Assert.AreEqual(10, ch.prize.gears);
    }

    [Test]
    public void DriverRuleAndMomentsAreExported()
    {
        var c = LoadChallenges();
        var great = c.GetChapter("the_closer_the_great_american");
        Assert.AreEqual(RestrictionRule.Driver, great.restriction.rule);
        Assert.AreEqual("Harvick", great.restriction.value);
        Assert.AreEqual(201, great.raceLaps);
        Assert.AreEqual(191, great.moment.startingLap);

        var boots = c.GetChapter("the_closer_big_boots_to_fill");
        Assert.AreEqual("cup01livery29", boots.moment.playerLivery);
        Assert.AreEqual("cup01", boots.moment.carset);
        Assert.AreEqual("cup01MomentsAtlanta", boots.moment.field);
        Assert.AreEqual("Atlanta01", boots.moment.name);
        CollectionAssert.AreEqual(new[] { "x", "player", "x", "x", "x", "x", "24" }, boots.moment.fieldOrder);
        Assert.AreEqual("cup01_29", Challenges.ProvidedCarId(boots));

        // DM2 set Chastain's starting lap twice; the later assignment (500 of 501) is the one that ran.
        var wall = c.GetChapter("modern_era_chastain_s_wallride");
        Assert.IsNotNull(wall);
        Assert.AreEqual(500, wall.moment.startingLap);
        Assert.AreEqual(501, wall.raceLaps);
        Assert.AreEqual("wallride", wall.moment.modifier);
        Assert.AreEqual(2, Challenges.LapsToRun(wall));
        Assert.AreEqual(40, Challenges.PlayerGridSlot(wall.moment));
    }

    [Test]
    public void EveryChapterRacesARealTrackWithAPayablePrize()
    {
        var cars = LoadCars();
        foreach (var ch in LoadChallenges().Events.SelectMany(e => e.chapters))
        {
            Assert.IsTrue(TrackDimensions.Has(ch.track), $"{ch.id}: '{ch.track}' is not a TrackCatalog id");
            Assert.Greater(Challenges.LapsToRun(ch), 0, ch.id);
            Assert.IsTrue(RestrictionRule.IsValid(ch.restriction.rule), ch.id);
            Assert.IsFalse(ch.prize.IsNone, $"{ch.id}: every DM2 chapter had a prize");
            Assert.IsNotEmpty(Challenges.PrizePool(ch.prize, cars), $"{ch.id}: prize {ch.prize.code} has no car");
            if (ch.prize.kind == ChallengePrizeKind.AltPaint)
                StringAssert.StartsWith(cars.Get(ch.prize.cars[0]).livery + "alt", ch.prize.livery, ch.id);
            if (!ch.ProvidesCar)
                Assert.IsNotEmpty(Restrictions.FittingCars(ch.restriction, cars), $"{ch.id}: no catalogue car can enter");
            if (ch.moment.HasFieldOrder)
                Assert.GreaterOrEqual(Challenges.PlayerGridSlot(ch.moment), 0, ch.id);
        }
    }

    [Test]
    public void OneStarPrizeIsOneStarCarsOnly()
    {
        var cars = LoadCars();
        var ch = LoadChallenges().GetChapter("classics_daytona_79");
        Assert.AreEqual(ChallengePrizeKind.Category, ch.prize.kind);
        Assert.AreEqual("1Star", ch.prize.code);
        var pool = Challenges.PrizePool(ch.prize, cars);
        Assert.IsTrue(pool.All(c => c.rarity == 1));
        Assert.AreEqual(cars.ByRarity(1).Count, pool.Count);
    }

    // ---- Weeks ------------------------------------------------------------------------------------------

    [Test]
    public void CycleWeekWrapsAfterThirteen()
    {
        Assert.AreEqual(1, Challenges.CycleWeek(1));
        Assert.AreEqual(13, Challenges.CycleWeek(13));
        Assert.AreEqual(1, Challenges.CycleWeek(14));
        Assert.AreEqual(4, Challenges.CycleWeek(17));
        Assert.AreEqual(13, Challenges.CycleWeek(0));
        Assert.AreEqual(1, Challenges.WeekForDay(0));
        Assert.AreEqual(1, Challenges.WeekForDay(6));
        Assert.AreEqual(2, Challenges.WeekForDay(7));
        Assert.AreEqual(1, Challenges.WeekForDay(13 * 7));
    }

    [Test]
    public void LiveEventsFollowTheWeeks()
    {
        var c = LoadChallenges();
        string[] Live(int week) => Challenges.LiveEvents(c, week).Select(e => e.id).ToArray();
        CollectionAssert.AreEqual(new[] { "ol_seven_time", "modern_era", "classics" }, Live(4));
        CollectionAssert.AreEqual(new[] { "the_closer", "modern_era", "classics" }, Live(1));
        CollectionAssert.AreEqual(Live(4), Live(17), "week 17 is week 4 of the next cycle");
        CollectionAssert.IsEmpty(Live(13), "nothing runs in week 13");
        // DM2 matched "12" as containing "1" and "2"; here week 12 doesn't light The Closer (1,5,9) or The Intimidator (2,6,10).
        CollectionAssert.AreEqual(new[] { "ol_seven_time", "modern_era", "classics" }, Live(12));
    }

    [Test]
    public void WeeksUntilLiveCountsAheadAcrossTheCycle()
    {
        var ev = LoadChallenges().Get("the_closer");   // 1, 5, 9
        Assert.AreEqual(0, Challenges.WeeksUntilLive(ev, 5));
        Assert.AreEqual(3, Challenges.WeeksUntilLive(ev, 6));
        Assert.AreEqual(4, Challenges.WeeksUntilLive(ev, 10), "10 -> 14 = week 1 of the next cycle");
        Assert.AreEqual(-1, Challenges.WeeksUntilLive(new ChallengeEvent(), 1));
    }

    // ---- Progress and entry -----------------------------------------------------------------------------

    [Test]
    public void ProgressionChaptersUnlockInOrder()
    {
        var ev = Event(ChallengeEventType.Progression, "a", "b", "c");
        var records = new List<ChallengeRecord>();
        Assert.IsTrue(Challenges.ChapterUnlocked(ev, 0, records));
        Assert.IsFalse(Challenges.ChapterUnlocked(ev, 1, records));
        Challenges.RecordResult(records, ev, ev.chapters[0], 3);
        Assert.IsFalse(Challenges.ChapterUnlocked(ev, 1, records), "a third place doesn't complete it");
        Challenges.RecordResult(records, ev, ev.chapters[0], 1);
        Assert.IsTrue(Challenges.ChapterUnlocked(ev, 1, records));
        Assert.IsFalse(Challenges.ChapterUnlocked(ev, 2, records));
        Assert.IsFalse(Challenges.ChapterUnlocked(ev, 3, records), "out of range");

        var p = Challenges.Progress(ev, records);
        Assert.AreEqual(1, p.completed);
        Assert.AreEqual(3, p.total);
        Assert.AreEqual(1, p.nextChapter);
        Assert.IsFalse(p.IsFinished);
    }

    [Test]
    public void ReplayChaptersAreAllOpen()
    {
        var ev = Event(ChallengeEventType.Replay, "a", "b", "c");
        for (int i = 0; i < 3; i++) Assert.IsTrue(Challenges.ChapterUnlocked(ev, i, null));
    }

    [Test]
    public void CanEnterChecksWeekChapterAndRestriction()
    {
        var ev = Event(ChallengeEventType.Progression, "a", "b");
        ev.chapters[0].restriction = new Restriction(5, 2, RestrictionRule.Team, "HEN");
        var hen = Car("t_48", 48, team: "HEN");
        var garage = new List<OwnedCar> { new OwnedCar("t_48", 2, 0) };
        var records = new List<ChallengeRecord>();

        var ok = Challenges.CanEnter(ev, ev.chapters[0], hen, garage, 5, 1, records);
        Assert.IsTrue(ok.Eligible, ok.Summary);

        var notLive = Challenges.CanEnter(ev, ev.chapters[0], hen, garage, 5, 2, records);
        Assert.IsFalse(notLive.Eligible);
        CollectionAssert.AreEqual(new[] { ChallengeLock.NotLive }, notLive.Locks);

        var lowLevel = Challenges.CanEnter(ev, ev.chapters[0], hen, garage, 4, 1, records);
        Assert.IsTrue(lowLevel.restriction.Has(RestrictionFailure.PlayerLevel));

        var wrongTeam = Challenges.CanEnter(ev, ev.chapters[0], Car("t_1", 1, team: "JGR"),
            new List<OwnedCar> { new OwnedCar("t_1", 3, 0) }, 5, 1, records);
        Assert.IsTrue(wrongTeam.restriction.Has(RestrictionFailure.Team));

        var lowClass = Challenges.CanEnter(ev, ev.chapters[0], hen, new List<OwnedCar> { new OwnedCar("t_48", 1, 0) }, 5, 1, records);
        Assert.IsTrue(lowClass.restriction.Has(RestrictionFailure.CarClass));

        var locked = Challenges.CanEnter(ev, ev.chapters[1], hen, garage, 5, 1, records);
        CollectionAssert.AreEqual(new[] { ChallengeLock.ChapterLocked }, locked.Locks);
        StringAssert.Contains("previous chapter", locked.Summary);
    }

    [Test]
    public void ProvidedCarChaptersSkipTheGarage()
    {
        var c = LoadChallenges();
        var ch = c.GetChapter("the_closer_heartbreaker");   // hands the player cup23livery4, L15 C3
        var ev = c.Get("the_closer");
        Assert.IsTrue(ch.ProvidesCar);
        var records = ev.chapters.Take(ev.IndexOf(ch)).Select(x => new ChallengeRecord { chapterId = x.id, attempts = 1, completions = 1 }).ToList();
        var entry = Challenges.CanEnter(ev, ch, null, new List<OwnedCar>(), 15, 1, records);
        Assert.IsTrue(entry.Eligible, entry.Summary);
        var low = Challenges.CanEnter(ev, ch, null, new List<OwnedCar>(), 14, 1, records);
        Assert.IsFalse(low.Eligible);
        Assert.IsTrue(low.restriction.Has(RestrictionFailure.PlayerLevel));
        Assert.AreEqual("cup23_4", Challenges.ProvidedCarId(ch));
    }

    [Test]
    public void RecordResultTracksCompletionAndPrizeDue()
    {
        var prog = Event(ChallengeEventType.Progression, "a");
        var records = new List<ChallengeRecord>();
        var lost = Challenges.RecordResult(records, prog, prog.chapters[0], 4);
        Assert.IsFalse(lost.completed);
        Assert.IsFalse(lost.prizeDue);
        var won = Challenges.RecordResult(records, prog, prog.chapters[0], 1);
        Assert.IsTrue(won.completed && won.firstCompletion && won.prizeDue);
        var r = Challenges.FindRecord(records, "a");
        Assert.AreEqual(2, r.attempts);
        Assert.AreEqual(1, r.completions);
        Assert.AreEqual(1, r.bestFinish);

        var moment = Challenges.RecordResult(records, prog, prog.chapters[0], 6, momentComplete: true);
        Assert.IsTrue(moment.completed, "a met moment completes whatever the position");
        Assert.IsFalse(moment.firstCompletion);
        Assert.AreEqual(1, r.bestFinish);
        Assert.AreEqual(1, Challenges.PrizesOwed(prog, prog.chapters[0], records), "Progression owes one prize however many wins");
    }

    // ---- Prizes -----------------------------------------------------------------------------------------

    [Test]
    public void NamedCarPrizeUnlocksThenBecomesGears()
    {
        var cars = SmallCatalog();
        var prize = new ChallengePrize { kind = ChallengePrizeKind.Car, code = "Johnson", cars = new List<string> { "t_48" }, gears = 20 };
        var garage = new List<OwnedCar>();

        var first = Challenges.ResolvePrize(prize, cars, garage, null, 1);
        Assert.AreEqual("t_48", first.carId);
        Assert.IsTrue(first.newCar);
        Assert.AreEqual(20, first.gears);
        CollectionAssert.IsEmpty(garage, "Resolve doesn't touch the garage");
        Challenges.ApplyPrize(first, garage, null);
        Assert.AreEqual(1, garage.Count);
        Assert.AreEqual(0, garage[0].carClass);
        Assert.AreEqual(20, garage[0].gears);

        var again = Challenges.ResolvePrize(prize, cars, garage, null, 2);
        Assert.IsFalse(again.newCar);
        Assert.AreEqual(20, again.gears);
        Challenges.ApplyPrize(again, garage, null);
        Assert.AreEqual(1, garage.Count);
        Assert.AreEqual(40, garage[0].gears);

        // No set prize: a new car gets the starter gears, a duplicate the duplicate gears.
        prize.gears = 0;
        Assert.AreEqual(CarProgression.DuplicateGears, Challenges.ResolvePrize(prize, cars, garage, null, 3).gears);
        Assert.AreEqual(CarProgression.StarterGears, Challenges.ResolvePrize(prize, cars, new List<OwnedCar>(), null, 3).gears);
        // A small set prize never leaves a new car short of class 1.
        prize.gears = 5;
        Assert.AreEqual(CarProgression.StarterGears, Challenges.ResolvePrize(prize, cars, new List<OwnedCar>(), null, 3).gears);
    }

    [Test]
    public void CategoryPrizeIsASeededPickFromTheFilter()
    {
        var cars = SmallCatalog();
        var prize = new ChallengePrize
        {
            kind = ChallengePrizeKind.Category, code = "1Star",
            filter = new PrizeFilter { code = "1Star", minRarity = 1, maxRarity = 1 },
        };
        CollectionAssert.AreEqual(new[] { "t_1", "t_2", "t_3", "t_4" }, Challenges.PrizePool(prize, cars).Select(c => c.id).ToArray());

        var garage = new List<OwnedCar>();
        var picks = new HashSet<string>();
        for (long seed = 0; seed < 40; seed++)
        {
            var a = Challenges.ResolvePrize(prize, cars, garage, null, seed);
            var b = Challenges.ResolvePrize(prize, cars, garage, null, seed);
            Assert.AreEqual(a.carId, b.carId, "same seed, same car");
            Assert.AreEqual(1, cars.Get(a.carId).rarity);
            picks.Add(a.carId);
        }
        Assert.AreEqual(4, picks.Count, "40 seeds reach every car in a pool of 4");
    }

    [Test]
    public void CategoryPrizeSkipsMaxClassCarsUnlessThatsAllThereIs()
    {
        var cars = SmallCatalog();
        var prize = new ChallengePrize
        {
            kind = ChallengePrizeKind.Category, code = "1Star",
            filter = new PrizeFilter { code = "1Star", minRarity = 1, maxRarity = 1 },
        };
        var garage = new List<OwnedCar>
        {
            new OwnedCar("t_1", CarProgression.MaxClass), new OwnedCar("t_2", CarProgression.MaxClass), new OwnedCar("t_3", CarProgression.MaxClass),
        };
        for (long seed = 0; seed < 20; seed++)
            Assert.AreEqual("t_4", Challenges.ResolvePrize(prize, cars, garage, null, seed).carId);
        garage.Add(new OwnedCar("t_4", CarProgression.MaxClass));
        var o = Challenges.ResolvePrize(prize, cars, garage, null, 7);
        Assert.IsTrue(o.PaysSomething);
        Assert.IsFalse(o.newCar);
    }

    [Test]
    public void AltPaintUnlocksOnceThenIsADuplicate()
    {
        var prize = new ChallengePrize { kind = ChallengePrizeKind.AltPaint, code = "AltPaint", livery = "t_livery48alt1", cars = new List<string> { "t_48" } };
        var paints = new List<string>();
        var garage = new List<OwnedCar>();
        var o = Challenges.ResolvePrize(prize, SmallCatalog(), garage, paints, 0);
        Assert.IsTrue(o.PaysSomething);
        Assert.AreEqual("t_48", o.carId);
        Challenges.ApplyPrize(o, garage, paints);
        CollectionAssert.AreEqual(new[] { "t_livery48alt1" }, paints);
        CollectionAssert.IsEmpty(garage, "an alt paint isn't a car");

        var dup = Challenges.ResolvePrize(prize, SmallCatalog(), garage, paints, 0);
        Assert.IsTrue(dup.duplicateAltPaint);
        Assert.IsFalse(dup.PaysSomething);
        Challenges.ApplyPrize(dup, garage, paints);
        Assert.AreEqual(1, paints.Count);
    }

    [Test]
    public void EmptyPoolAndNoPrizePayNothing()
    {
        var cars = SmallCatalog();
        var garage = new List<OwnedCar>();
        var none = Challenges.ResolvePrize(new ChallengePrize(), cars, garage, null, 0);
        Assert.IsFalse(none.PaysSomething);
        var missing = Challenges.ResolvePrize(new ChallengePrize { kind = ChallengePrizeKind.Car, code = "X", cars = new List<string> { "nope_1" } }, cars, garage, null, 0);
        Assert.IsTrue(missing.emptyPool);
        Challenges.ApplyPrize(missing, garage, null);
        CollectionAssert.IsEmpty(garage);
    }

    [Test]
    public void ProgressionPaysOnceReplayPaysEveryCompletion()
    {
        var cars = SmallCatalog();
        var garage = new List<OwnedCar>();
        var prog = Event(ChallengeEventType.Progression, "p");
        var records = new List<ChallengeRecord>();
        Assert.IsFalse(Challenges.ClaimPrize(prog, prog.chapters[0], records, cars, garage, null, 9).PaysSomething, "not completed yet");
        Challenges.RecordResult(records, prog, prog.chapters[0], 1);
        Assert.IsTrue(Challenges.HasUnclaimedPrize(prog, prog.chapters[0], records));
        var paid = Challenges.ClaimPrize(prog, prog.chapters[0], records, cars, garage, null, 9);
        Assert.IsTrue(paid.newCar);
        Assert.IsFalse(Challenges.HasUnclaimedPrize(prog, prog.chapters[0], records));
        Assert.IsFalse(Challenges.ClaimPrize(prog, prog.chapters[0], records, cars, garage, null, 9).PaysSomething, "claimed already");
        var rerun = Challenges.RecordResult(records, prog, prog.chapters[0], 1);
        Assert.IsTrue(rerun.completed);
        Assert.IsFalse(rerun.prizeDue, "a won Progression chapter pays once");
        Assert.AreEqual(20, garage[0].gears);

        var replay = Event(ChallengeEventType.Replay, "r");
        var rr = new List<ChallengeRecord>();
        var g2 = new List<OwnedCar>();
        for (int i = 0; i < 3; i++)
        {
            Assert.IsTrue(Challenges.RecordResult(rr, replay, replay.chapters[0], 1).prizeDue);
            Assert.IsTrue(Challenges.ClaimPrize(replay, replay.chapters[0], rr, cars, g2, null, 9).PaysSomething);
            Assert.IsFalse(Challenges.ClaimPrize(replay, replay.chapters[0], rr, cars, g2, null, 9).PaysSomething, "one prize per completion");
        }
        Assert.AreEqual(60, g2[0].gears, "20 new + 20 + 20");
        Assert.AreEqual(3, Challenges.FindRecord(rr, "r").prizesPaid);
    }

    [Test]
    public void PrizeSeedIsStableAndMovesWithTheCompletion()
    {
        Assert.AreEqual(Challenges.PrizeSeed(5, "a", 1), Challenges.PrizeSeed(5, "a", 1));
        Assert.AreNotEqual(Challenges.PrizeSeed(5, "a", 1), Challenges.PrizeSeed(5, "a", 2));
        Assert.AreNotEqual(Challenges.PrizeSeed(5, "a", 1), Challenges.PrizeSeed(5, "b", 1));
        Assert.AreNotEqual(Challenges.PrizeSeed(5, "a", 1), Challenges.PrizeSeed(6, "a", 1));
    }

    // ---- Laps, grid, save hygiene -----------------------------------------------------------------------

    [Test]
    public void RaceLapsFallBackToTheSeriesFormula()
    {
        var c = LoadChallenges();
        var daytona = c.GetChapter("ol_seven_time_daytona");   // no raceLaps; Daytona base 4, ai 9 -> x3
        Assert.AreEqual(SeriesRules.RaceLaps(4, 9), Challenges.RaceLaps(daytona));
        Assert.AreEqual(1, Challenges.StartingLap(daytona));
        Assert.AreEqual(Challenges.RaceLaps(daytona), Challenges.LapsToRun(daytona));

        var wheels = c.GetChapter("modern_era_wide_open_wheels");   // starts lap 14, no raceLaps: Fort Worth 5 x (10/4+1) = 15
        Assert.AreEqual(15, Challenges.RaceLaps(wheels));
        Assert.AreEqual(2, Challenges.LapsToRun(wheels));
    }

    [Test]
    public void GridCarsSkipEmptySlots()
    {
        var m = new ChallengeMoment { fieldOrder = new List<string> { "97", "x", "x", "x", "player" } };
        Assert.AreEqual(4, Challenges.PlayerGridSlot(m));
        var cars = Challenges.GridCars(m);
        Assert.AreEqual(1, cars.Count);
        Assert.AreEqual(0, cars[0].slot);
        Assert.AreEqual(97, cars[0].number);
        Assert.AreEqual(-1, Challenges.PlayerGridSlot(new ChallengeMoment()));
    }

    [Test]
    public void SanitiseMergesAndClamps()
    {
        var records = new List<ChallengeRecord>
        {
            null,
            new ChallengeRecord { chapterId = "" },
            new ChallengeRecord { chapterId = "a", attempts = 1, completions = 1, bestFinish = 3, prizesPaid = 4 },
            new ChallengeRecord { chapterId = "a", attempts = -2, completions = 2, bestFinish = 1 },
            new ChallengeRecord { chapterId = "b", attempts = -1, completions = -1, bestFinish = -5, prizesPaid = -1 },
        };
        Challenges.Sanitise(records);
        Assert.AreEqual(2, records.Count);
        var a = records[0];
        Assert.AreEqual("a", a.chapterId);
        Assert.AreEqual(3, a.completions);
        Assert.AreEqual(3, a.attempts, "attempts never below completions");
        Assert.AreEqual(1, a.bestFinish);
        Assert.AreEqual(3, a.prizesPaid, "never more prizes than completions");
        var b = records[1];
        Assert.AreEqual(0, b.attempts + b.completions + b.bestFinish + b.prizesPaid);
    }

    [Test]
    public void CatalogueDropsBrokenRows()
    {
        var file = new ChallengesFile
        {
            version = 1,
            events = new List<ChallengeEvent>
            {
                null,
                new ChallengeEvent { id = "empty", chapters = new List<ChallengeChapter> { new ChallengeChapter { id = "no_track" } } },
                new ChallengeEvent
                {
                    id = "ok", weeks = null,
                    chapters = new List<ChallengeChapter>
                    {
                        new ChallengeChapter { id = "x", track = "Daytona", moment = null, prize = null, restriction = null },
                        new ChallengeChapter { id = "x", track = "Bristol" },
                    },
                },
            },
        };
        var c = new ChallengeCatalog(file);
        Assert.AreEqual(1, c.Events.Count);
        Assert.AreEqual(Challenges.DefaultCycleWeeks, c.CycleWeeks);
        var x = c.GetChapter("x");
        Assert.AreEqual("Daytona", x.track, "a repeated id keeps the first row");
        Assert.AreEqual("ok", x.eventId);
        Assert.IsNotNull(x.moment);
        Assert.IsTrue(x.prize.IsNone);
        Assert.IsNotNull(x.restriction);
        Assert.IsNull(ChallengeCatalog.FromJson(""));
    }
